<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Facades\Hash;
use Illuminate\Validation\ValidationException;
class ApiController extends Controller {
 private function cfg(string $resource):array{$c=config("donarconecta.resources.$resource");abort_unless($c,404);return $c;}
 private function allow(Request $r,array $roles):void {abort_unless($r->user()->status==='ACTIVO'&&in_array($r->user()->role?->name,$roles,true),403,'Sin permiso');}
 private function log(Request $r,string $action,string $record):void{DB::table('bitacora')->insert(['user_id'=>$r->user()->id,'usuario'=>$r->user()->name,'accion'=>$action,'registro'=>$record,'created_at'=>now(),'updated_at'=>now()]);}
 public function index(Request $r,string $resource){$c=$this->cfg($resource);$this->allow($r,$c['read']);$q=DB::table($c['table']);if($search=trim((string)$r->query('search',''))){$fields=array_intersect($c['fields'],['name','nombre','apellido','empresa','email','recurso','descripcion','observaciones']);if($fields)$q->where(function($b)use($fields,$search){foreach($fields as $f)$b->orWhere($f,'like','%'.$search.'%');});}foreach(['estado','status','donante_id','beneficiario_id','tipo_donacion_id'] as $key)if(in_array($key,$c['fields'],true)&&$r->filled($key))$q->where($key,$r->query($key));if(in_array('fecha_recepcion',$c['fields'],true)){if($r->filled('fecha_inicio'))$q->whereDate('fecha_recepcion','>=',$r->query('fecha_inicio'));if($r->filled('fecha_fin'))$q->whereDate('fecha_recepcion','<=',$r->query('fecha_fin'));}return $q->orderByDesc('id')->limit(500)->get()->map(fn($item)=>$this->safe($item));}
 public function show(Request $r,string $resource,int $id){$c=$this->cfg($resource);$this->allow($r,$c['read']);return $this->safe(DB::table($c['table'])->find($id)??abort(404));}
 private function safe($o){$a=(array)$o;unset($a['password'],$a['remember_token']);return $a;}
 private function validateData(Request $r,string $resource,bool $create):array{
  $rules=match($resource){
   'users'=>['name'=>'required|string|max:255','email'=>'required|email|max:255|unique:users,email'.($create?'':','.$r->route('id')),'password'=>($create?'required':'sometimes').'|string|min:12','role_id'=>'required|exists:roles,id','status'=>'in:ACTIVO,INACTIVO'],
   'donantes'=>['tipo_donante'=>'required|in:PERSONA,EMPRESA','nombre'=>'required|string|max:255','apellido'=>'nullable|string|max:255','empresa'=>'nullable|string|max:255','telefono'=>'nullable|string|max:80','email'=>'nullable|email','direccion'=>'nullable|string','estado'=>'in:ACTIVO,INACTIVO'],
   'tipos-donacion'=>['nombre'=>'required|string|max:255','descripcion'=>'nullable|string'],
   'donaciones'=>['donante_id'=>'required|exists:donantes,id','tipo_donacion_id'=>'required|exists:tipos_donacion,id','cantidad'=>'required|integer|min:1','fecha_recepcion'=>'required|date','estado'=>'in:RECIBIDA,DISPONIBLE,ASIGNADA,ENTREGADA,CANCELADA','observaciones'=>'nullable|string'],
   'beneficiarios'=>['nombre'=>'required|string','telefono'=>'nullable|string','direccion'=>'nullable|string','necesidad'=>'nullable|string','estado'=>'in:ACTIVO,INACTIVO'],
   'solicitudes'=>['beneficiario_id'=>'required|exists:beneficiarios,id','tipo_necesidad'=>'required|string','fecha'=>'required|date','descripcion'=>'nullable|string','estado'=>'in:PENDIENTE,APROBADA,ATENDIDA,RECHAZADA'],
   default=>[]};return $r->validate($rules);
 }
 public function store(Request $r,string $resource){$c=$this->cfg($resource);$this->allow($r,$c['write']);abort_if(in_array($resource,['asignaciones','entregas','inventario','roles','bitacora'],true),405);$v=$this->validateData($r,$resource,true);return DB::transaction(function()use($r,$resource,$c,$v){if($resource==='donaciones'){$v['estado']='DISPONIBLE';}if($resource==='users')$v['password']=Hash::make($v['password']);$id=DB::table($c['table'])->insertGetId($v+['created_at'=>now(),'updated_at'=>now()]);if($resource==='donaciones'){$tipo=DB::table('tipos_donacion')->find($v['tipo_donacion_id']);$inv=DB::table('inventario')->insertGetId(['donacion_id'=>$id,'recurso'=>$tipo->nombre,'existencia'=>$v['cantidad'],'ubicacion'=>'Bodega central','created_at'=>now(),'updated_at'=>now()]);$this->move($r,$inv,'ENTRADA',$v['cantidad']);}$this->log($r,'CREAR_'.strtoupper($resource),$resource.' #'.$id);return response()->json($this->safe(DB::table($c['table'])->find($id)),201);});}
 public function update(Request $r,string $resource,int $id){$c=$this->cfg($resource);$this->allow($r,$c['write']);abort_if(in_array($resource,['donaciones','asignaciones','entregas','inventario','roles','bitacora'],true),405,'Registros históricos inmutables');$v=$this->validateData($r,$resource,false);if($resource==='users'&&isset($v['password']))$v['password']=Hash::make($v['password']);abort_unless(DB::table($c['table'])->where('id',$id)->exists(),404);DB::table($c['table'])->where('id',$id)->update($v+['updated_at'=>now()]);$this->log($r,'ACTUALIZAR_'.strtoupper($resource),$resource.' #'.$id);return $this->safe(DB::table($c['table'])->find($id));}
 public function state(Request $r,string $resource,int $id){$c=$this->cfg($resource);$this->allow($r,$c['write']);abort_unless(in_array($resource,['solicitudes','beneficiarios','donantes'],true),405);$v=$r->validate(['estado'=>'required|string|in:ACTIVO,INACTIVO,PENDIENTE,APROBADA,ATENDIDA,RECHAZADA']);abort_unless(DB::table($c['table'])->where('id',$id)->exists(),404);DB::table($c['table'])->where('id',$id)->update(['estado'=>$v['estado'],'updated_at'=>now()]);$this->log($r,'CAMBIAR_ESTADO',$resource.' #'.$id);return $this->safe(DB::table($c['table'])->find($id));}
 private function move(Request $r,int $id,string $type,int $q):void{DB::table('movimientos_inventario')->insert(['inventario_id'=>$id,'user_id'=>$r->user()->id,'tipo'=>$type,'cantidad'=>$q,'created_at'=>now(),'updated_at'=>now()]);}
 public function movement(Request $r,string $type){$this->allow($r,['Administrador','Encargado de inventario']);$v=$r->validate(['inventario_id'=>'required|exists:inventario,id','cantidad'=>'required|integer|min:1']);return DB::transaction(function()use($r,$type,$v){$row=DB::table('inventario')->where('id',$v['inventario_id'])->lockForUpdate()->first();$delta=$type==='entrada'?$v['cantidad']:-$v['cantidad'];if($row->existencia+$delta<0)throw ValidationException::withMessages(['cantidad'=>'Inventario insuficiente']);DB::table('inventario')->where('id',$row->id)->update(['existencia'=>$row->existencia+$delta,'updated_at'=>now()]);$this->move($r,$row->id,strtoupper($type),$v['cantidad']);$this->log($r,'INVENTARIO_'.strtoupper($type),'inventario #'.$row->id);return DB::table('inventario')->find($row->id);});}
 public function assignment(Request $r){$this->allow($r,['Administrador','Encargado de donaciones','Encargado de inventario','Encargado de entregas']);$v=$r->validate(['beneficiario_id'=>'required|exists:beneficiarios,id','inventario_id'=>'required|exists:inventario,id','solicitud_id'=>'nullable|exists:solicitudes,id','cantidad'=>'required|integer|min:1']);return DB::transaction(function()use($r,$v){$inv=DB::table('inventario')->where('id',$v['inventario_id'])->lockForUpdate()->first();if($inv->existencia<$v['cantidad'])throw ValidationException::withMessages(['cantidad'=>'Inventario insuficiente']);DB::table('inventario')->where('id',$inv->id)->update(['existencia'=>$inv->existencia-$v['cantidad'],'updated_at'=>now()]);$id=DB::table('asignaciones')->insertGetId($v+['estado'=>'PENDIENTE','created_at'=>now(),'updated_at'=>now()]);$this->move($r,$inv->id,'RESERVA',$v['cantidad']);$this->log($r,'CREAR_ASIGNACION','asignaciones #'.$id);return response()->json(DB::table('asignaciones')->find($id),201);});}
 public function delivery(Request $r){$this->allow($r,['Administrador','Encargado de entregas']);$v=$r->validate(['asignacion_id'=>'required|exists:asignaciones,id','cantidad'=>'required|integer|min:1','fecha'=>'required|date','responsable_id'=>'required|exists:users,id','observaciones'=>'nullable|string']);return DB::transaction(function()use($r,$v){$a=DB::table('asignaciones')->where('id',$v['asignacion_id'])->lockForUpdate()->first();$delivered=(int)DB::table('entregas')->where('asignacion_id',$a->id)->sum('cantidad');if($v['cantidad']+$delivered>$a->cantidad)throw ValidationException::withMessages(['cantidad'=>'Excede lo asignado']);$id=DB::table('entregas')->insertGetId($v+['created_at'=>now(),'updated_at'=>now()]);DB::table('asignaciones')->where('id',$a->id)->update(['estado'=>$v['cantidad']+$delivered===$a->cantidad?'ENTREGADA':'PARCIAL','updated_at'=>now()]);$this->move($r,$a->inventario_id,'ENTREGA',$v['cantidad']);$this->log($r,'CREAR_ENTREGA','entregas #'.$id);return response()->json(DB::table('entregas')->find($id),201);});}
 public function evidence(Request $r,int $id){$this->allow($r,['Administrador','Encargado de entregas']);abort_unless(DB::table('entregas')->where('id',$id)->exists(),404);$file=$r->validate(['archivo'=>'required|file|mimes:pdf,jpg,jpeg,png|max:5120'])['archivo'];$path=$file->store('evidencias','local');DB::table('evidencias')->insert(['entrega_id'=>$id,'archivo'=>$path,'nombre_original'=>$file->getClientOriginalName(),'mime'=>$file->getMimeType(),'bytes'=>$file->getSize(),'created_at'=>now(),'updated_at'=>now()]);$this->log($r,'SUBIR_EVIDENCIA','entregas #'.$id);return response()->json(['success'=>true],201);}
 public function evidenceList(Request $r,int $id){$this->allow($r,['Administrador','Encargado de entregas','Supervisor']);return DB::table('evidencias')->where('entrega_id',$id)->get(['id','nombre_original','mime','bytes','created_at']);}
 public function movements(Request $r,?int $id=null){$this->allow($r,['Administrador','Encargado de inventario','Supervisor']);$q=DB::table('movimientos_inventario');if($id)$q->where('inventario_id',$id);return $q->orderByDesc('id')->limit(500)->get();}
 public function history(Request $r,int $id){$this->allow($r,['Administrador','Encargado de donaciones','Supervisor']);abort_unless(DB::table('donaciones')->where('id',$id)->exists(),404);return $this->tracking($r,$id);}
 public function tracking(Request $r,int $id){$this->allow($r,['Administrador','Encargado de donaciones','Supervisor']);$d=DB::table('donaciones')->find($id);abort_unless($d,404);$inv=DB::table('inventario')->where('donacion_id',$id)->first();$as=DB::table('asignaciones')->where('inventario_id',$inv?->id??0)->get();return ['donacion'=>$d,'donante'=>DB::table('donantes')->find($d->donante_id),'inventario'=>$inv,'asignaciones'=>$as,'entregas'=>DB::table('entregas')->whereIn('asignacion_id',$as->pluck('id'))->get(),'historial'=>DB::table('movimientos_inventario')->where('inventario_id',$inv?->id??0)->orderBy('id')->get()];}
 public function related(Request $r,string $table,int $id,string $related){$allowed=match($table){'donantes'=>['donaciones'=>['donaciones','donante_id']],'beneficiarios'=>['solicitudes'=>['solicitudes','beneficiario_id'],'ayudas'=>['asignaciones','beneficiario_id']],default=>[]};abort_unless(isset($allowed[$related]),404);$this->allow($r,['Administrador','Encargado de donaciones','Encargado de entregas','Supervisor']);[$t,$fk]=$allowed[$related];return DB::table($t)->where($fk,$id)->get();}
 public function dashboard(Request $r){abort_if(!$r->user(),401);return ['donaciones_recibidas'=>DB::table('donaciones')->count(),'donaciones_pendientes'=>DB::table('donaciones')->whereNotIn('estado',['ENTREGADA','CANCELADA'])->count(),'donaciones_entregadas'=>DB::table('entregas')->count(),'beneficiarios'=>DB::table('beneficiarios')->count(),'donantes'=>DB::table('donantes')->count(),'recursos_disponibles'=>(int)DB::table('inventario')->sum('existencia')];}
 public function report(Request $r,string $type){$this->allow($r,['Administrador','Supervisor']);$t=match($type){'donaciones-recibidas','donaciones-periodo'=>'donaciones','donaciones-entregadas'=>'entregas','donaciones-pendientes'=>'donaciones','donantes'=>'donantes','beneficiarios'=>'beneficiarios','inventario'=>'inventario','movimientos'=>'movimientos_inventario',default=>null};abort_unless($t,404);$q=DB::table($t);if($type==='donaciones-pendientes')$q->whereNotIn('estado',['ENTREGADA','CANCELADA']);if($type==='donaciones-periodo'||$type==='donaciones-recibidas'){$q->when($r->query('fecha_inicio'),fn($q,$date)=>$q->whereDate('fecha_recepcion','>=',$date))->when($r->query('fecha_fin'),fn($q,$date)=>$q->whereDate('fecha_recepcion','<=',$date));}if($type==='inventario')$q->where('existencia','>',0);return $q->orderByDesc('id')->limit(1000)->get();}
 public function userStatus(Request $r,int $id){$this->allow($r,['Administrador']);$v=$r->validate(['status'=>'required|in:ACTIVO,INACTIVO']);abort_if($id===$r->user()->id&&$v['status']==='INACTIVO',422,'No puedes desactivar tu propia cuenta');DB::table('users')->where('id',$id)->update(['status'=>$v['status']]);$this->log($r,'ESTADO_USUARIO','users #'.$id);return $this->safe(DB::table('users')->find($id));}
}
